// -13 thanks to Nguyen2007 ⚡
float toAngle(float t) {
    float frac = t - floor(t);  // equivalent to fract(x)
    return tan(frac * 1.57)/(1.0 + tan(frac * 1.57));
}

float rsin(float angle) {
    // Remove square root by squaring both sides
    return angle * inversesqrt(1.0 - 2.0 * angle + 2.0 * angle * angle);
}

float rcos(float angle) {
    return (1.0 - angle) * inversesqrt(1.0 - 2.0 * angle + 2.0 * angle * angle);
}

vec2 posAt(float param, float time) {
    float rs = rsin(param);
    float rc = rcos(param);

    /*   -x,+y|+x,+y
        ___q2_|__q3__
         -x,-y|+x,-y
           q1 |  q0    */

    int quadrant = int(mod(time, 4.0) * 4.0);
    bool isEven = (quadrant & 1) == 0;// & 1 same as % 2
    bool isFirstHalf = quadrant < 2;

    float x = isEven ? rc : rs;
    float y = isEven ? rs : rc;

    y = isFirstHalf ? y : -y;
    x = (quadrant == 0 || quadrant == 3) ? x : -x;

    return vec2(x, y);
}



